p.table:


    Guest Name
    Guest Qty
    Arrival Time
    Rooms
    Departure Date

% for o in ctx.get('stay_list'):


    ${o['partner_name']}
    ${o['guest_qty']}
    ${o['arrival_time']}
    ${o['rooms']}
    ${format_date(o['departure_date'])} ${o['departure_time']}

% endfor

div.ul:

Stay Number: ${object.name}

Guest: ${object.partner_name}

Guest Qty: ${object.guest_qty}

Arrival Date: ${format_date(object.arrival_date)}

Arrival Time: ${dict(object.fields_get('arrival_time', 'selection')['arrival_time']['selection'])[object.arrival_time]}
                % if object.arrival_note:

Arrival Note: ${object.arrival_note}
                % endif

Departure Date: ${format_date(object.departure_date)}

Departure Time: ${dict(object.fields_get('departure_time', 'selection')['departure_time']['selection'])[object.departure_time]}
                % if object.departure_note:

Departure Note: ${object.departure_note}
                % endif
                % if object.group_id:

Group: ${object.group_id.display_name}
                % endif
                % if object.controller_email:

E-mail: ${object.controller_email}
                % endif
                % if object.controller_mobile:

Phone: ${object.controller_mobile}
                % endif
                % if object.controller_notes:

Notes: ${object.controller_notes}
                % endif
